// Symbols to watch — keep in sync with WATCHLIST in main.py
const WATCHLIST = ['AAPL', 'MSFT', 'NVDA'];
return WATCHLIST.map(symbol => ({ json: { symbol } }));

// Parse RSS XML and extract latest 5 headlines
const xml = $input.first().json.data;
const matches = [...xml.matchAll(/<title><!\[CDATA\[(.+?)\]\]><\/title>/g)];
const symbol = $('Build Symbol List').first().json.symbol;

return matches.slice(1, 6).map(m => ({
  json: { symbol, headline: m[1].trim() }
}));

// Simple keyword-based sentiment scoring.
// Replace this node with an AI/LLM node for better accuracy.
const headline = $json.headline.toLowerCase();
const symbol = $json.symbol;

const bullish = ['beat', 'surges', 'record', 'growth', 'upgrade', 'buy', 'rally', 'profit', 'strong', 'outperform'];
const bearish = ['miss', 'drops', 'falls', 'lawsuit', 'downgrade', 'sell', 'loss', 'weak', 'cut', 'concern', 'recall', 'fine'];

let score = 0;
bullish.forEach(w => { if (headline.includes(w)) score += 0.25; });
bearish.forEach(w => { if (headline.includes(w)) score -= 0.25; });
score = Math.max(-1, Math.min(1, score));

const sentiment = score > 0.1 ? 'positive' : score < -0.1 ? 'negative' : 'neutral';

return [{ json: { symbol, headline: $json.headline, sentiment, score } }];
